import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const isNonnegativeSafeInteger = value => Number.isSafeInteger(value) && value >= 0;

export function packContext(sections, maxBytes) {
  if (!isNonnegativeSafeInteger(maxBytes)) {
    throw new Error('maxBytes must be a nonnegative safe integer');
  }
  if (!Array.isArray(sections)) throw new Error('sections must be a dense array');

  const ids = new Set();
  const entries = [];
  // Validate every entry before making any selection, including at zero budget.
  for (let index = 0; index < sections.length; index++) {
    if (!Object.hasOwn(sections, index)) throw new Error('sections must be dense');
    const section = sections[index];
    if (section === null || typeof section !== 'object' || Array.isArray(section)) {
      throw new Error('Each section must be an object');
    }
    const { id, text, priority, required } = section;
    if (typeof id !== 'string' || id.length === 0 || typeof text !== 'string' ||
        !isNonnegativeSafeInteger(priority) || typeof required !== 'boolean') {
      throw new Error('Invalid section fields');
    }
    if (ids.has(id)) throw new Error('Duplicate section ID');
    ids.add(id);
    entries.push({ id, text, priority, required, index });
  }

  for (const entry of entries) {
    entry.frame = '### ' + JSON.stringify(entry.id) + '\n' + entry.text + '\n';
    entry.cost = Buffer.byteLength(entry.frame, 'utf8');
  }
  let remaining = maxBytes;
  const frames = [];
  const included = [];
  const selected = new Set();
  const include = entry => {
    remaining -= entry.cost;
    frames.push(entry.frame);
    included.push(entry.id);
    selected.add(entry.id);
  };
  for (const entry of entries) {
    if (!entry.required) continue;
    if (entry.cost > remaining) throw new Error('Required sections exceed maxBytes');
    include(entry);
  }
  const optional = entries.filter(entry => !entry.required);
  optional.sort((a, b) => b.priority - a.priority || a.index - b.index);
  for (const entry of optional) {
    if (entry.cost <= remaining) include(entry);
  }
  const text = frames.join('');
  return {
    text,
    bytes: Buffer.byteLength(text, 'utf8'),
    included,
    omitted: entries.filter(entry => !entry.required && !selected.has(entry.id))
      .map(entry => entry.id),
  };
}

function main() {
  try {
    if (process.argv.length !== 3) throw new Error('Usage: node context-packet.js INPUT_JSON_FILE');
    const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    if (input === null || typeof input !== 'object' || Array.isArray(input)) {
      throw new Error('Input must be an object containing sections and maxBytes');
    }
    const result = packContext(input.sections, input.maxBytes);
    process.stdout.write(JSON.stringify(result) + '\n');
  } catch (error) {
    process.stderr.write((error instanceof Error ? error.message : String(error)) + '\n');
    process.exitCode = 2;
  }
}

if (process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url) {
  main();
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { packContext } from '../context-packet.js';

const section = (id, text = '', priority = 0, required = false) => ({ id, text, priority, required });
const frame = s => '### ' + JSON.stringify(s.id) + '\n' + s.text + '\n';
const cost = s => Buffer.byteLength(frame(s), 'utf8');

test('numeric boundaries and strict field validation, even for omitted sections', () => {
  const invalidNumbers = [-1, 0.5, NaN, Infinity, -Infinity, Number.MAX_SAFE_INTEGER + 1, '0', null, undefined, true, 0n];
  for (const value of invalidNumbers) {
    assert.throws(() => packContext([], value), Error);
    assert.throws(() => packContext([{ ...section('x'), priority: value }], 0), Error);
  }
  assert.deepEqual(packContext([], Number.MAX_SAFE_INTEGER), { text: '', bytes: 0, included: [], omitted: [] });
  assert.deepEqual(packContext([section('x', '', Number.MAX_SAFE_INTEGER)], Number.MAX_SAFE_INTEGER).included, ['x']);
  for (const input of [null, {}, 'abc', undefined, new Array(1), [null], [[]], [1], [() => {}]]) {
    assert.throws(() => packContext(input, 0), Error);
  }
  for (const field of ['id', 'text', 'priority', 'required']) {
    const input = section('x');
    delete input[field];
    assert.throws(() => packContext([input], 0), Error);
  }
  for (const patch of [{ id: '' }, { id: 1 }, { text: null }, { text: 2 }, { required: 0 }, { required: 'false' }]) {
    assert.throws(() => packContext([{ ...section('x'), ...patch }], 0), Error);
  }
  assert.throws(() => packContext([section('same'), section('same')], 0), Error);
  const sparse = new Array(1);
  Object.setPrototypeOf(sparse, Object.assign(Object.create(Array.prototype), { 0: section('inherited') }));
  assert.throws(() => packContext(sparse, 0), Error);
});

test('exact framing preserves special IDs, UTF-8 and source whitespace without mutation', () => {
  const ids = ['__proto__', 'constructor', 'A', 'a', ' ', '\n', '\u0000', '雪', '"\\', '\ud800'];
  const sections = Object.freeze(ids.map(id => Object.freeze({ ...section(id, ' \r\n雪é😀\n '), ignored: 42 })));
  const text = sections.map(frame).join('');
  const bytes = Buffer.byteLength(text);
  assert.deepEqual(packContext(sections, bytes), { text, bytes, included: ids, omitted: [] });
  const result = packContext(sections, 0);
  assert.deepEqual(result, { text: '', bytes: 0, included: [], omitted: ids });
});

test('required order, stable priorities, skipping and original omission order', () => {
  const sections = [
    section('low-big', 'x'.repeat(100), 0),
    section('tie-a', '', 3),
    section('req-a', '', 0, true),
    section('high-big', 'x'.repeat(100), 10),
    section('tie-b', '', 3),
    section('req-b', '', 100, true),
    section('last', '', 1),
  ];
  const expected = [sections[2], sections[5], sections[1], sections[4]];
  const text = expected.map(frame).join('');
  assert.deepEqual(packContext(sections, Buffer.byteLength(text)), {
    text, bytes: Buffer.byteLength(text), included: expected.map(s => s.id), omitted: ['low-big', 'high-big', 'last'],
  });
  assert.throws(() => packContext(sections, cost(sections[2]) + cost(sections[5]) - 1), Error);
  const one = section('é', '😀', 0, true);
  assert.equal(packContext([one], cost(one)).text, frame(one));
  assert.throws(() => packContext([one], cost(one) - 1), Error);
});

test('CLI success, failures and import isolation', () => {
  const directory = mkdtempSync(join(tmpdir(), 'context-packet-'));
  const cli = fileURLToPath(new URL('../context-packet.js', import.meta.url));
  const run = args => spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });
  const failure = args => {
    const result = run(args);
    assert.ifError(result.error);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.length > 0);
  };
  try {
    const file = join(directory, 'input.json');
    const sections = [section('雪', ' é\n', 1, true)];
    writeFileSync(file, JSON.stringify({ sections, maxBytes: 100, extra: 'ignored' }));
    const result = run([file]);
    assert.ifError(result.error);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, JSON.stringify(packContext(sections, 100)) + '\n');
    failure([]);
    failure([file, file]);
    failure([join(directory, 'missing.json')]);
    failure([directory]);
    for (const content of ['{', 'null', '[]', '{}', '{"sections":[],"maxBytes":9007199254740992}', JSON.stringify({ sections, maxBytes: 0 }), JSON.stringify({ sections: [{ id: 'x', text: '', priority: 0 }], maxBytes: 0 })]) {
      writeFileSync(file, content);
      failure([file]);
    }
    const imported = spawnSync(process.execPath, ['--input-type=module', '-e', `await import(${JSON.stringify(new URL('../context-packet.js', import.meta.url).href)})`], { encoding: 'utf8' });
    assert.ifError(imported.error);
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
});

