+  assert.deepEqual(packContext([section('x', '', Number.MAX_SAFE_INTEGER)], Number.MAX_SAFE_INTEGER).included, ['x']);
+  for (const input of [null, {}, 'abc', undefined, new Array(1), [null], [[]], [1], [() => {}]]) {
+    assert.throws(() => packContext(input, 0), Error);
+  }
+  for (const field of ['id', 'text', 'priority', 'required']) {
+    const input = section('x');
+    delete input[field];
+    assert.throws(() => packContext([input], 0), Error);
+  }
+  for (const patch of [{ id: '' }, { id: 1 }, { text: null }, { text: 2 }, { required: 0 }, { required: 'false' }]) {
+    assert.throws(() => packContext([{ ...section('x'), ...patch }], 0), Error);
+  }
+  assert.throws(() => packContext([section('same'), section('same')], 0), Error);
+  const sparse = new Array(1);
+  Object.setPrototypeOf(sparse, Object.assign(Object.create(Array.prototype), { 0: section('inherited') }));
+  assert.throws(() => packContext(sparse, 0), Error);
+});
+
+test('exact framing preserves special IDs, UTF-8 and source whitespace without mutation', () => {
+  const ids = ['__proto__', 'constructor', 'A', 'a', ' ', '\n', '\u0000', '雪', '"\\', '\ud800'];
+  const sections = Object.freeze(ids.map(id => Object.freeze({ ...section(id, ' \r\n雪é😀\n '), ignored: 42 })));
+  const text = sections.map(frame).join('');
+  const bytes = Buffer.byteLength(text);
+  assert.deepEqual(packContext(sections, bytes), { text, bytes, included: ids, omitted: [] });
+  const result = packContext(sections, 0);
+  assert.deepEqual(result, { text: '', bytes: 0, included: [], omitted: ids });
+});
+
+test('required order, stable priorities, skipping and original omission order', () => {
+  const sections = [
+    section('low-big', 'x'.repeat(100), 0),
+    section('tie-a', '', 3),
+    section('req-a', '', 0, true),
+    section('high-big', 'x'.repeat(100), 10),
+    section('tie-b', '', 3),
+    section('req-b', '', 100, true),
+    section('last', '', 1),
+  ];
+  const expected = [sections[2], sections[5], sections[1], sections[4]];
+  const text = expected.map(frame).join('');
+  assert.deepEqual(packContext(sections, Buffer.byteLength(text)), {
+    text, bytes: Buffer.byteLength(text), included: expected.map(s => s.id), omitted: ['low-big', 'high-big', 'last'],
+  });
+  assert.throws(() => packContext(sections, cost(sections[2]) + cost(sections[5]) - 1), Error);
+  const one = section('é', '😀', 0, true);
+  assert.equal(packContext([one], cost(one)).text, frame(one));
+  assert.throws(() => packContext([one], cost(one) - 1), Error);
+});
+
+test('CLI success, failures and import isolation', () => {
+  const directory = mkdtempSync(join(tmpdir(), 'context-packet-'));
+  const cli = fileURLToPath(new URL('../context-packet.js', import.meta.url));
+  const run = args => spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });
+  const failure = args => {
+    const result = run(args);
+    assert.ifError(result.error);
+    assert.equal(result.status, 2);
+    assert.equal(result.stdout, '');
+    assert.ok(result.stderr.length > 0);
+  };
+  try {
+    const file = join(directory, 'input.json');
+    const sections = [section('雪', ' é\n', 1, true)];
+    writeFileSync(file, JSON.stringify({ sections, maxBytes: 100, extra: 'ignored' }));
+    const result = run([file]);
+    assert.ifError(result.error);
+    assert.equal(result.status, 0);
+    assert.equal(result.stderr, '');
+    assert.equal(result.stdout, JSON.stringify(packContext(sections, 100)) + '\n');
+    failure([]);
+    failure([file, file]);
+    failure([join(directory, 'missing.json')]);
+    failure([directory]);
+    for (const content of ['{', 'null', '[]', '{}', '{"sections":[],"maxBytes":9007199254740992}', JSON.stringify({ sections, maxBytes: 0 }), JSON.stringify({ sections: [{ id: 'x', text: '', priority: 0 }], maxBytes: 0 })]) {
+      writeFileSync(file, content);
+      failure([file]);
+    }
+    const imported = spawnSync(process.execPath, ['--input-type=module', '-e', `await import(${JSON.stringify(new URL('../context-packet.js', import.meta.url).href)})`], { encoding: 'utf8' });
+    assert.ifError(imported.error);
+    assert.equal(imported.status, 0);
+    assert.equal(imported.stdout, '');
+    assert.equal(imported.stderr, '');
+  } finally {
+    rmSync(directory, { recursive: true, force: true });
+  }
+});

